'use client';

import { useId, useState } from 'react';

import { MailIcon, UserRoundPlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import {
  CURRENT_USER_NAME,
  INVITATIONS,
  MEMBERS,
  ROLE_LABEL,
  TEAM_NAME,
  type Invitation,
  type Role,
} from './data';
import { InvitationList, LIST_SURFACE } from './invitation-list';
import { InviteSheet, type InviteTab } from './invite-sheet';

function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${plural}`;
}

function invitationOf(email: string, role: Role): Invitation {
  return {
    id: `invite-${email}`,
    email,
    role,
    invitedBy: CURRENT_USER_NAME,
    sentLabel: 'Sent just now',
  };
}

export default function Team03() {
  const [invitations, setInvitations] = useState<Invitation[]>(INVITATIONS);
  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const [sheetTab, setSheetTab] = useState<InviteTab>('invite');
  const pendingHeadingId = useId();
  const membersHeadingId = useId();
  const hasInvitations = invitations.length > 0;
  const memberText = countLabel(MEMBERS.length, 'member', 'members');
  const pendingText = countLabel(
    invitations.length,
    'pending invitation',
    'pending invitations'
  );

  function openInvite() {
    setSheetTab('invite');
    setIsSheetOpen(true);
  }

  function openInvited() {
    setSheetTab('invited');
    setIsSheetOpen(true);
  }

  function send(emails: string[], role: Role) {
    const created = emails.map((email) => invitationOf(email, role));
    setInvitations((previous) => [...created, ...previous]);
  }

  function resend(invitationId: string) {
    setInvitations((previous) =>
      previous.map((invitation) => {
        if (invitation.id !== invitationId) {
          return invitation;
        }
        return { ...invitation, sentLabel: 'Sent again just now' };
      })
    );
  }

  function revoke(invitationId: string) {
    setInvitations((previous) =>
      previous.filter((invitation) => invitation.id !== invitationId)
    );
  }

  return (
    <div className='bg-background text-foreground flex min-h-dvh w-full flex-col'>
      <div className='hairline-b border-border flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3 md:px-6'>
        <div className='flex min-w-0 items-baseline gap-2'>
          <h1 className='truncate text-lg font-semibold'>{`${TEAM_NAME} team`}</h1>
          <span className='text-muted-foreground text-xs tabular-nums'>
            {`${memberText} · ${pendingText}`}
          </span>
        </div>
        <div className='ml-auto flex items-center gap-2'>
          <Button
            variant='outline'
            onClick={openInvited}
            className='hidden sm:inline-flex'
          >
            <MailIcon />
            Invited
          </Button>
          <Button onClick={openInvite}>
            <UserRoundPlusIcon />
            Invite people
          </Button>
        </div>
      </div>
      <div className='mx-auto flex w-full max-w-3xl flex-col gap-8 px-4 py-6 md:px-6'>
        <section
          aria-labelledby={pendingHeadingId}
          className='flex flex-col gap-3'
        >
          <div className='flex items-baseline gap-2'>
            <h2 id={pendingHeadingId} className='text-sm font-medium'>
              Pending invitations
            </h2>
            <span className='text-muted-foreground text-xs tabular-nums'>
              {invitations.length}
            </span>
          </div>
          {hasInvitations && (
            <InvitationList
              invitations={invitations}
              onResend={resend}
              onRevoke={revoke}
            />
          )}
          {!hasInvitations && (
            <div className='hairline-border border-foreground/20 flex flex-col items-center gap-3 rounded-xl border-dashed px-4 py-10 text-center'>
              <div className='flex flex-col gap-1'>
                <p className='text-sm font-medium'>No pending invitation</p>
                <p className='text-muted-foreground text-[13px]'>
                  Everyone you invited has joined or the invitation was revoked
                </p>
              </div>
              <Button variant='outline' onClick={openInvite}>
                Invite people
              </Button>
            </div>
          )}
        </section>
        <section
          aria-labelledby={membersHeadingId}
          className='flex flex-col gap-3'
        >
          <div className='flex items-baseline gap-2'>
            <h2 id={membersHeadingId} className='text-sm font-medium'>
              Members
            </h2>
            <span className='text-muted-foreground text-xs tabular-nums'>
              {MEMBERS.length}
            </span>
          </div>
          <ul className={LIST_SURFACE}>
            {MEMBERS.map((member) => (
              <li
                key={member.id}
                className='flex min-h-14 items-center gap-3 px-3 py-2.5'
              >
                <Avatar>
                  {member.avatar && <AvatarImage src={member.avatar} alt='' />}
                  <AvatarFallback>{member.initials}</AvatarFallback>
                </Avatar>
                <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
                  <p className='truncate text-[13px] font-medium'>
                    {member.name}
                  </p>
                  <p className='text-muted-foreground truncate text-xs'>
                    {member.email}
                  </p>
                </div>
                <Chip color='var(--muted-foreground)'>
                  {ROLE_LABEL[member.role]}
                </Chip>
              </li>
            ))}
          </ul>
        </section>
      </div>
      <InviteSheet
        open={isSheetOpen}
        onOpenChange={setIsSheetOpen}
        tab={sheetTab}
        onTabChange={setSheetTab}
        teamName={TEAM_NAME}
        members={MEMBERS}
        invitations={invitations}
        onSend={send}
        onResend={resend}
        onRevoke={revoke}
      />
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useId, useState } from 'react';

import { MailIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';
import { RadioGroup, RadioGroupItem } from '@/registry/ndeko/ui/radio-group';
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/registry/ndeko/ui/sheet';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/registry/ndeko/ui/tabs';
import { Textarea } from '@/registry/ndeko/ui/textarea';

import { ROLE_OPTIONS, type Invitation, type Member, type Role } from './data';
import { EmailChipsField } from './email-chips-field';
import { InvitationList } from './invitation-list';

export type InviteTab = 'invite' | 'invited';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const LABEL_MORPH: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const DIGIT_SHIFT_PX = 8;

const DIGIT_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const DIGIT_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * DIGIT_SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * DIGIT_SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

type ParsedEmails = { accepted: string[]; rejected: string[]; reason: string };

type CountState = { value: number; direction: number };

function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LABEL_MORPH;
}

function digitVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return DIGIT_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

function isInviteTab(value: unknown): value is InviteTab {
  const isInvite = value === 'invite';
  const isInvited = value === 'invited';
  return isInvite || isInvited;
}

function isRole(value: unknown): value is Role {
  return ROLE_OPTIONS.some((option) => option.value === value);
}

function sendLabelOf(count: number) {
  if (count > 1) {
    return `Send ${count} invitations`;
  }
  return 'Send invitation';
}

function rejectionOf(
  address: string,
  takenByMember: Set<string>,
  invited: Set<string>
) {
  const isEmail = EMAIL_PATTERN.test(address);
  if (!isEmail) {
    return `${address} is not an e-mail address`;
  }
  if (takenByMember.has(address)) {
    return `${address} is already in the team`;
  }
  if (invited.has(address)) {
    return `${address} already has an invitation`;
  }
  return null;
}

function SlidingCount({ value }: { value: number }) {
  const shouldReduceMotion = useReducedMotion();
  const [shown, setShown] = useState<CountState>({ value, direction: 1 });
  const variants = digitVariantsOf(shouldReduceMotion);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span className='bg-foreground/[0.06] text-muted-foreground relative inline-flex h-5 min-w-5 items-center justify-center overflow-hidden rounded-sm px-1.5 text-xs tabular-nums'>
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={value}
          custom={shown.direction}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={DIGIT_TRANSITION}
        >
          {value}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

type InviteSheetProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tab: InviteTab;
  onTabChange: (tab: InviteTab) => void;
  teamName: string;
  members: Member[];
  invitations: Invitation[];
  onSend: (emails: string[], role: Role) => void;
  onResend: (invitationId: string) => void;
  onRevoke: (invitationId: string) => void;
};

export function InviteSheet({
  open,
  onOpenChange,
  tab,
  onTabChange,
  teamName,
  members,
  invitations,
  onSend,
  onResend,
  onRevoke,
}: InviteSheetProps) {
  const [emails, setEmails] = useState<string[]>([]);
  const [draft, setDraft] = useState('');
  const [role, setRole] = useState<Role>('member');
  const [note, setNote] = useState('');
  const [error, setError] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const labelMorph = morphOf(shouldReduceMotion);
  const fieldId = useId();
  const hintId = useId();
  const noteId = useId();
  const hasError = Boolean(error);
  const hasInvitations = invitations.length > 0;
  const hasDraft = draft.trim().length > 0;
  let sendCount = emails.length;
  if (hasDraft) {
    sendCount += 1;
  }
  const canSend = sendCount > 0;

  function parse(text: string, current: string[]): ParsedEmails {
    const memberEmails = new Set(members.map((member) => member.email));
    const invitedEmails = new Set(invitations.map((item) => item.email));
    const parts = text.split(/[\s,;]+/);
    const accepted: string[] = [];
    const rejected: string[] = [];
    let reason = '';
    for (const part of parts) {
      const address = part.trim().toLowerCase();
      const isEmpty = address.length === 0;
      const isKnown = current.includes(address) || accepted.includes(address);
      if (isEmpty || isKnown) {
        continue;
      }
      const rejection = rejectionOf(address, memberEmails, invitedEmails);
      if (rejection) {
        rejected.push(address);
        if (!reason) {
          reason = rejection;
        }
        continue;
      }
      accepted.push(address);
    }
    return { accepted, rejected, reason };
  }

  function commit(text: string) {
    const parsed = parse(text, emails);
    setEmails((previous) => [...previous, ...parsed.accepted]);
    setDraft(parsed.rejected.join(' '));
    const hasRejected = parsed.rejected.length > 0;
    if (hasRejected) {
      setError(parsed.reason);
      return;
    }
    setError(null);
  }

  function changeDraft(nextDraft: string) {
    setDraft(nextDraft);
    setError(null);
  }

  function removeEmail(email: string) {
    setEmails((previous) => previous.filter((item) => item !== email));
  }

  function changeRole(value: unknown) {
    if (isRole(value)) {
      setRole(value);
    }
  }

  function changeNote(event: React.ChangeEvent<HTMLTextAreaElement>) {
    setNote(event.target.value);
  }

  function changeTab(value: unknown) {
    if (isInviteTab(value)) {
      onTabChange(value);
    }
  }

  function showInviteTab() {
    onTabChange('invite');
  }

  function send(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const parsed = parse(draft, emails);
    const hasRejected = parsed.rejected.length > 0;
    if (hasRejected) {
      setEmails((previous) => [...previous, ...parsed.accepted]);
      setDraft(parsed.rejected.join(' '));
      setError(parsed.reason);
      return;
    }
    const allEmails = [...emails, ...parsed.accepted];
    if (allEmails.length === 0) {
      setError('Add at least one e-mail address');
      return;
    }
    onSend(allEmails, role);
    setEmails([]);
    setDraft('');
    setNote('');
    setError(null);
    onTabChange('invited');
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className='bottom-auto max-h-[calc(100dvh-1rem)] max-w-md gap-0 p-0'>
        <SheetHeader className='px-5 pt-5 pb-3'>
          <SheetTitle>{`Invite to ${teamName}`}</SheetTitle>
          <SheetDescription>
            People join the team once they accept the e-mail
          </SheetDescription>
        </SheetHeader>
        <Tabs value={tab} onValueChange={changeTab} className='gap-0'>
          <TabsList aria-label='Invitations' className='mx-5'>
            <TabsTab value='invite'>Invite</TabsTab>
            <TabsTab value='invited'>
              Invited
              <SlidingCount value={invitations.length} />
            </TabsTab>
          </TabsList>
          <AnimatedSize className='m-0' contentClassName='p-0'>
            <TabsPanel value='invite' className='rounded-none'>
              <form
                onSubmit={send}
                className='flex flex-col gap-5 px-5 pt-4 pb-5'
              >
                <div className='flex flex-col gap-1.5'>
                  <label htmlFor={fieldId} className='text-[13px] font-medium'>
                    E-mail addresses
                  </label>
                  <EmailChipsField
                    id={fieldId}
                    emails={emails}
                    draft={draft}
                    isInvalid={hasError}
                    describedBy={hintId}
                    onDraftChange={changeDraft}
                    onCommit={commit}
                    onRemove={removeEmail}
                  />
                  <p
                    id={hintId}
                    className={cn(
                      'text-xs',
                      hasError && 'text-destructive-ink',
                      !hasError && 'text-muted-foreground'
                    )}
                  >
                    {error ?? 'Separate addresses with a comma or a space'}
                  </p>
                </div>
                <fieldset className='flex flex-col gap-1.5'>
                  <legend className='mb-1.5 text-[13px] font-medium'>
                    Role
                  </legend>
                  <RadioGroup
                    value={role}
                    onValueChange={changeRole}
                    className='bg-card hairline-ring ring-border hairline-divide-y divide-border gap-0 overflow-hidden rounded-xl'
                  >
                    {ROLE_OPTIONS.map((option) => {
                      const isPicked = option.value === role;

                      return (
                        <label
                          key={option.value}
                          className={cn(
                            'flex cursor-pointer items-start gap-3 px-3 py-2.5 transition-colors duration-150',
                            isPicked && 'bg-primary/[0.06]'
                          )}
                        >
                          <RadioGroupItem
                            value={option.value}
                            className='mt-0.5'
                          />
                          <span className='flex min-w-0 flex-col gap-0.5'>
                            <span className='text-[13px] font-medium'>
                              {option.label}
                            </span>
                            <span className='text-muted-foreground text-xs'>
                              {option.line}
                            </span>
                          </span>
                        </label>
                      );
                    })}
                  </RadioGroup>
                </fieldset>
                <div className='flex flex-col gap-1.5'>
                  <label htmlFor={noteId} className='text-[13px] font-medium'>
                    Note
                    <span className='text-muted-foreground font-normal'>
                      {' '}
                      (optional)
                    </span>
                  </label>
                  <Textarea
                    id={noteId}
                    value={note}
                    placeholder='Added to the invitation e-mail'
                    onChange={changeNote}
                  />
                </div>
                <div className='flex items-center justify-end gap-2'>
                  <SheetClose render={<Button type='button' variant='ghost' />}>
                    Cancel
                  </SheetClose>
                  <Button type='submit' disabled={!canSend}>
                    <MailIcon />
                    <motion.span layout transition={labelMorph}>
                      {sendLabelOf(sendCount)}
                    </motion.span>
                  </Button>
                </div>
              </form>
            </TabsPanel>
            <TabsPanel value='invited' className='rounded-none'>
              <div className='flex flex-col gap-3 px-5 pt-4 pb-5'>
                {hasInvitations && (
                  <InvitationList
                    invitations={invitations}
                    isCompact
                    onResend={onResend}
                    onRevoke={onRevoke}
                  />
                )}
                {!hasInvitations && (
                  <div className='hairline-border border-foreground/20 flex flex-col items-center gap-3 rounded-xl border-dashed px-4 py-8 text-center'>
                    <p className='text-sm font-medium'>No pending invitation</p>
                    <Button variant='outline' onClick={showInviteTab}>
                      Invite people
                    </Button>
                  </div>
                )}
              </div>
            </TabsPanel>
          </AnimatedSize>
        </Tabs>
      </SheetContent>
    </Sheet>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { useRef } from 'react';

import { XIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';

const SEPARATOR_KEYS = new Set(['Enter', ',', ' ', 'Tab']);

const CHIP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.23, 1, 0.32, 1],
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9 },
  shown: { opacity: 1, scale: 1 },
};

const CHIP_FADE: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return CHIP_FADE;
  }
  return CHIP_PRESENCE;
}

type EmailChipsFieldProps = {
  id: string;
  emails: string[];
  draft: string;
  isInvalid: boolean;
  describedBy?: string;
  onDraftChange: (draft: string) => void;
  onCommit: (text: string) => void;
  onRemove: (email: string) => void;
};

/** Addresses become chips on Enter, comma or space; a pasted list splits into chips. */
export function EmailChipsField({
  id,
  emails,
  draft,
  isInvalid,
  describedBy,
  onDraftChange,
  onCommit,
  onRemove,
}: EmailChipsFieldProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const chipVariants = chipVariantsOf(shouldReduceMotion);
  const hasDraft = draft.trim().length > 0;
  const lastEmail = emails.at(-1);

  function focusInput() {
    inputRef.current?.focus();
  }

  function changeDraft(event: React.ChangeEvent<HTMLInputElement>) {
    onDraftChange(event.target.value);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    const isSeparator = SEPARATOR_KEYS.has(event.key);
    const commitsDraft = isSeparator && hasDraft;
    if (commitsDraft) {
      event.preventDefault();
      onCommit(draft);
      return;
    }
    const isBackspace = event.key === 'Backspace';
    const removesLast = isBackspace && !hasDraft;
    if (removesLast && lastEmail) {
      onRemove(lastEmail);
    }
  }

  function handlePaste(event: React.ClipboardEvent<HTMLInputElement>) {
    const pasted = event.clipboardData.getData('text');
    const hasSeveral = /[\s,;]/.test(pasted.trim());
    if (hasSeveral) {
      event.preventDefault();
      onCommit(pasted);
    }
  }

  function commitOnBlur() {
    if (hasDraft) {
      onCommit(draft);
    }
  }

  return (
    <div
      onClick={focusInput}
      data-invalid={isInvalid || undefined}
      className={cn(
        CONTROL_RECIPE,
        'flex min-h-9 cursor-text flex-wrap items-center gap-1 px-1.5 py-1',
        'focus-within:border-foreground/30 focus-within:ring-ring/25 focus-within:ring-[3px]'
      )}
    >
      <AnimatePresence initial={false}>
        {emails.map((email) => {
          function removeEmail() {
            onRemove(email);
            focusInput();
          }

          return (
            <motion.span
              key={email}
              layout
              variants={chipVariants}
              initial='hidden'
              animate='shown'
              exit='hidden'
              transition={CHIP_TRANSITION}
              className='flex'
            >
              <Chip
                color='var(--muted-foreground)'
                className='h-6 max-w-56 gap-1 pr-0.5 pl-2 text-[13px]'
              >
                <span className='truncate'>{email}</span>
                <button
                  type='button'
                  aria-label={`Remove ${email}`}
                  onClick={removeEmail}
                  className='hover:bg-foreground/10 focus-visible:ring-ring/25 flex size-5 cursor-pointer items-center justify-center rounded-[5px] outline-none focus-visible:ring-[3px]'
                >
                  <XIcon className='size-3' />
                </button>
              </Chip>
            </motion.span>
          );
        })}
      </AnimatePresence>
      <input
        ref={inputRef}
        id={id}
        type='email'
        multiple
        autoComplete='off'
        value={draft}
        aria-invalid={isInvalid}
        aria-describedby={describedBy}
        placeholder='name@company.com'
        onChange={changeDraft}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
        onBlur={commitOnBlur}
        className='placeholder:text-muted-foreground/75 h-6 min-w-40 flex-1 bg-transparent px-1 text-base outline-none md:text-[13px]'
      />
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { MailIcon, SendIcon, TrashIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/registry/ndeko/ui/tooltip';

import { ROLE_LABEL, type Invitation } from './data';

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ROW_PRESENCE: Variants = {
  hidden: { height: 0, opacity: 0, transition: PRESENCE_OUT },
  shown: { height: 'auto', opacity: 1, transition: PRESENCE_IN },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

export const LIST_SURFACE =
  'bg-card hairline-ring ring-border hairline-divide-y divide-border overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function SentLine({ invitation }: { invitation: Invitation }) {
  const shouldReduceMotion = useReducedMotion();
  const variants = swapVariantsOf(shouldReduceMotion);
  const line = `Invited by ${invitation.invitedBy} · ${invitation.sentLabel}`;

  return (
    <span className='text-muted-foreground relative flex min-w-0 text-xs'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={line}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP_TRANSITION}
          className='truncate'
        >
          {line}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

function IconAction({
  label,
  hint,
  isDestructive = false,
  onClick,
  children,
}: {
  label: string;
  hint: string;
  isDestructive?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            variant='ghost'
            size='icon-sm'
            aria-label={label}
            onClick={onClick}
            className={cn(
              'text-muted-foreground',
              isDestructive &&
                'hover:bg-destructive/10 hover:text-destructive-ink'
            )}
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipContent>{hint}</TooltipContent>
    </Tooltip>
  );
}

type InvitationListProps = {
  invitations: Invitation[];
  isCompact?: boolean;
  onResend: (invitationId: string) => void;
  onRevoke: (invitationId: string) => void;
};

export function InvitationList({
  invitations,
  isCompact = false,
  onResend,
  onRevoke,
}: InvitationListProps) {
  const shouldReduceMotion = useReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);

  return (
    <ul className={LIST_SURFACE}>
      <AnimatePresence initial={false}>
        {invitations.map((invitation) => {
          function resend() {
            onResend(invitation.id);
          }

          function revoke() {
            onRevoke(invitation.id);
          }

          return (
            <motion.li
              key={invitation.id}
              variants={rowVariants}
              initial='hidden'
              animate='shown'
              exit='hidden'
              className='overflow-hidden'
            >
              <div className='flex min-h-14 items-center gap-3 px-3 py-2.5'>
                {!isCompact && (
                  <span className='keycap-3d text-muted-foreground hidden size-8 shrink-0 items-center justify-center rounded-full sm:flex'>
                    <MailIcon className='size-4' />
                  </span>
                )}
                <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
                  <p className='truncate text-[13px] font-medium'>
                    {invitation.email}
                  </p>
                  <SentLine invitation={invitation} />
                </div>
                <Chip
                  color='var(--muted-foreground)'
                  className='hidden sm:inline-flex'
                >
                  {ROLE_LABEL[invitation.role]}
                </Chip>
                <div className='flex shrink-0 items-center'>
                  <IconAction
                    label={`Resend to ${invitation.email}`}
                    hint='Resend'
                    onClick={resend}
                  >
                    <SendIcon />
                  </IconAction>
                  <IconAction
                    label={`Revoke the invitation of ${invitation.email}`}
                    hint='Revoke'
                    isDestructive
                    onClick={revoke}
                  >
                    <TrashIcon />
                  </IconAction>
                </div>
              </div>
            </motion.li>
          );
        })}
      </AnimatePresence>
    </ul>
  );
}

